# Colours:
#
# Black: #2b2b2b which has #ffffff text and controller body
# Blue: #0047ab which has #ffffff text and controller body
# Gold: #ffd700 which has #000000 text and controller body
# Green: #2baf2b which has #000000 text and controller body
# Red: #c80000 which has #000000 text and controller body
# Yellow: #ffd700 which has #000000 text and controller body

# Path: Cards/hucard_n64.svg

import os
import shutil
import subprocess
import sys
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import List, Tuple

from lxml import etree

# Gold is: <linearGradient
#    id="linearGradient1"
#    inkscape:collect="always"><stop
#      style="stop-color:#ffd700;stop-opacity:1;"
#      offset="0"
#      id="stop1" /><stop
#      style="stop-color:#d4af37;stop-opacity:1;"
#      offset="0.5"
#      id="stop8" /><stop
#      style="stop-color:#bfa54f;stop-opacity:1;"
#      offset="1"
#      id="stop2" /></linearGradient>

#   <path
#    id="Header-Background"
#    d="M 609.575,48.573997 V 207.50599 c 0,9.958 -8.084,18.042 -18.041,18.042 H 27.466 c -9.957,0 -18.041,-8.084 -18.041,-18.042 V 48.573997 Z"
#    style="fill:url(#linearGradient2);fill-opacity:1"
#    sodipodi:nodetypes="csssscc" />

# Define the cartridge colors and their corresponding text colors
cartridge_colors = {
    "Black": ("#2b2b2b", "#ffffff", "#222222"),
    "Blue": ("#0047ab", "#ffffff", "#003366"),
    "Gold": ("", "#000000", "#a98c2c"),
    "Green": ("#2baf2b", "#000000", "#228c22"),
    "Red": ("#c80000", "#000000", "#a00000"),
    "Yellow": ("#ffd700", "#000000", "#ccac00"),
}


def create_n64_cartridge_svg(
    base_svg_path: str, output_dir: str, cartridge_colors: dict
) -> List[str]:
    created_files = []
    for color_name, (
        cartridge_color,
        text_color,
        shade_color,
    ) in cartridge_colors.items():
        # Create a copy of the base SVG
        output_svg_path = Path(output_dir) / f"hucard_n64_{color_name.lower()}.svg"
        shutil.copy(base_svg_path, output_svg_path)

        # Modify the SVG content
        tree = ET.parse(output_svg_path)
        root = tree.getroot()

        # Define namespaces
        ns = {
            "svg": "http://www.w3.org/2000/svg",
            "sodipodi": "http://sodipodi.sourceforge.net/DTD/sodipodi-0.dtd",
            "inkscape": "http://www.inkscape.org/namespaces/inkscape",
        }

        # Update the cartridge color
        header_background = root.find(".//svg:path[@id='Header-Background']", ns)
        if color_name == "Gold":
            # Insert gradient if not present
            defs = root.find(".//svg:defs", ns)
            if defs is None:
                defs = ET.SubElement(root, "{http://www.w3.org/2000/svg}defs")
            gradient = root.find(".//svg:linearGradient[@id='linearGradientGold']", ns)
            if gradient is None:
                gradient = ET.SubElement(
                    defs,
                    "{http://www.w3.org/2000/svg}linearGradient",
                    {
                        "id": "linearGradientGold",
                        "x1": "-0.12096094",
                        "y1": "0.98514783",
                        "x2": "0.12096094",
                        "y2": "0.014852136",
                    },
                )
                ET.SubElement(
                    gradient,
                    "{http://www.w3.org/2000/svg}stop",
                    {"offset": "0%", "style": "stop-color:#ffd700;stop-opacity:1;"},
                )
                ET.SubElement(
                    gradient,
                    "{http://www.w3.org/2000/svg}stop",
                    {"offset": "50%", "style": "stop-color:#d4af37;stop-opacity:1;"},
                )
                ET.SubElement(
                    gradient,
                    "{http://www.w3.org/2000/svg}stop",
                    {"offset": "100%", "style": "stop-color:#bfa54f;stop-opacity:1;"},
                )
            if header_background is not None:
                header_background.set(
                    "style", "fill:url(#linearGradientGold);fill-opacity:1"
                )
        else:
            if header_background is not None:
                header_background.set("style", f"fill:{cartridge_color};fill-opacity:1")

        # Update the text color
        nfc_loading = root.find(".//svg:path[@id='NFC_LOADING']", ns)
        if nfc_loading is not None:
            nfc_loading.set("style", f"fill:{text_color};fill-opacity:1")

        # Update the controller body, dpad and stick colour (find it by inkscape label)
        controller_body = root.find(".//svg:path[@inkscape:label='body']", ns)
        if controller_body is not None:
            controller_body.set("style", f"fill:{text_color};fill-opacity:1")

        controller_dpad = root.find(".//svg:path[@inkscape:label='dpad']", ns)
        if controller_dpad is not None:
            controller_dpad.set("style", f"fill:{text_color};fill-opacity:1")

        controller_stick = root.find(".//svg:path[@inkscape:label='stick']", ns)
        if controller_stick is not None:
            controller_stick.set("style", f"fill:{text_color};fill-opacity:1")

        # Update the shade colour (find it by inkscape label "left-indent" and "vertical-line")
        left_indent = root.find(".//svg:path[@inkscape:label='left-indent']", ns)
        if left_indent is not None:
            left_indent.set("style", f"fill:{shade_color};fill-opacity:1")

        vertical_line = root.find(".//svg:path[@inkscape:label='vertical-line']", ns)
        if vertical_line is not None:
            vertical_line.set("style", f"fill:{shade_color};fill-opacity:1")

        # Save the modified SVG
        tree.write(output_svg_path)
        created_files.append(str(output_svg_path))
    return created_files


def main():
    base_svg_path = "Cards/hucard_n64.svg"
    output_dir = "Cards"
    create_n64_cartridge_svg(base_svg_path, output_dir, cartridge_colors)
    print("N64 cartridge SVG files created successfully.")
    print("Created files:")
    for file in create_n64_cartridge_svg(base_svg_path, output_dir, cartridge_colors):
        print(file)


if __name__ == "__main__":
    main()
